(function () {
if (typeof config.username !== 'string') throw new Error('必须配置字符串 username');
var username = config.username.trim().replace(/^wxchannels:/, '').trim();
if (!username || username.indexOf('REPLACE_') >= 0) throw new Error('请在自动化配置中填写创作者 username');
if (!/@finder$/.test(username)) username += '@finder';
return {username:username,remark:String(config.remark || '')};
})()

(function () {
var method = String(config.push_method || '').trim();
if (method !== 'wecom' && method !== 'webhook') throw new Error('消息推送方式必须选择企业微信机器人或通用 HTTP Webhook');
var address = String(config.push_url || '').trim();
if (!/^https?:\/\/[^\s#]+$/i.test(address) || address.indexOf('REPLACE_') >= 0) throw new Error('请配置完整 HTTP(S) 推送接口地址');
var token = String(config.push_token || '').trim();
if (/[\r\n]/.test(token)) throw new Error('token 不能包含换行');
if (method === 'wecom') {
  if (token) {
    var encoded = encodeURIComponent(token);
    address = /([?&])key=[^&]*/.test(address) ? address.replace(/([?&])key=[^&]*/, function (_, separator) { return separator + 'key=' + encoded; }) : address + (address.indexOf('?') >= 0 ? '&' : '?') + 'key=' + encoded;
  } else if (!/[?&]key=[^&#]+/.test(address)) throw new Error('企业微信推送需要在 token 或接口地址中填写机器人 key');
}
var template = String(config.message_template || '');
if (!template.trim()) template = '创作者发布了新视频\n账号：{username}\n标题：{title}\n视频 ID：{video_id}\n发布时间：{published_at}';
var allowed = {username:true,remark:true,title:true,video_id:true,published_at:true};
(template.match(/\{([^{}]+)\}/g) || []).forEach(function (placeholder) {
  var name = placeholder.slice(1, -1);
  if (!Object.prototype.hasOwnProperty.call(allowed, name)) throw new Error('消息模板包含未知占位符：' + placeholder);
});
return {method:method,url:address,auth_type:method === 'webhook' && token ? 'bearer' : 'none',token:method === 'webhook' ? token : '',message_template:template};
})()

(function () {
if (!(global.max_pages > 0) || Math.floor(global.max_pages) !== global.max_pages || !(global.max_videos > 0) || Math.floor(global.max_videos) !== global.max_videos) throw new Error('max_pages 和 max_videos 必须为正整数');
var response = output.fetch_page.page_result;
if (!response || (response.errCode !== undefined && Number(response.errCode) !== 0) || (response.code !== undefined && Number(response.code) !== 0)) throw new Error('获取视频列表失败');
var data = response.data;
if (!data || !Array.isArray(data.object)) throw new Error('视频列表响应缺少 data.object');
if (data.BaseResponse && Number(data.BaseResponse.ret || 0) !== 0) throw new Error('视频列表 BaseResponse 返回错误');
if (data.continueFlag === undefined || data.continueFlag === null || !isFinite(Number(data.continueFlag))) throw new Error('视频列表缺少有效 continueFlag');
var state = JSON.parse(JSON.stringify(global.scan_state));
state.page += 1;
if (state.page > global.max_pages) throw new Error('超过 max_pages，本次同步未完成');
state.items = []; state.pending = []; state.all_existing = false;
var page_ids = {};
function id_string(value) {
  if (typeof value === 'number' && (!isFinite(value) || Math.floor(value) !== value || Math.abs(value) > 9007199254740991)) throw new Error('平台返回不安全的数字 ID，需要字符串 ID');
  return value === undefined || value === null ? '' : String(value);
}
for (var i = 0; i < data.object.length; i++) {
  var item = data.object[i], desc = item.objectDesc || {}, media = desc.media || [];
  if (Number(desc.mediaType) !== 4 && !media.some(function (m) { return Number(m.mediaType) === 4; })) continue;
  var oid = id_string(item.id), nid = id_string(item.objectNonceId);
  if (!oid || !nid) throw new Error('视频缺少 id 或 objectNonceId');
  if (page_ids[oid]) continue;
  page_ids[oid] = true; state.seen_ids[oid] = true;
  state.items.push({oid: oid, nid: nid, title: String(desc.description || ''), published_at: item.createtime || item.createTime || 0});
}
if (Object.keys(state.seen_ids).length > global.max_videos) throw new Error('超过 max_videos，本次扫描未完成');
state.has_more = Number(data.continueFlag) !== 0;
state.next_cursor = data.lastBuffer || '';
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
var response = output.check_videos.checks;
if (!response || !Array.isArray(response.list) || response.total !== state.items.length || response.list.length !== state.items.length) throw new Error('批量视频存在性检查结果不完整');
var checks = Object.create(null);
response.list.forEach(function (check) {
  if (!check || typeof check.content_id !== 'string' || Object.prototype.hasOwnProperty.call(checks, check.content_id) || typeof check.exists !== 'boolean' || typeof check.task_count !== 'number' || !isFinite(check.task_count) || check.task_count < 0 || Math.floor(check.task_count) !== check.task_count || check.exists !== (check.task_count > 0)) throw new Error('批量视频存在性检查结果无效');
  checks[check.content_id] = check;
});
state.pending = [];
for (var i = 0; i < state.items.length; i++) {
  var video = state.items[i], content_id = 'wxchannels:' + video.oid;
  if (!Object.prototype.hasOwnProperty.call(checks, content_id)) throw new Error('批量检查缺少视频 ' + video.oid);
  var check = checks[content_id];
  state.checked += 1;
  if (check.exists) state.skipped += 1;
  else {
    state.pending.push(video);
    if (!Object.prototype.hasOwnProperty.call(state.candidate_ids, video.oid)) {
      state.candidate_ids[video.oid] = true;
      state.videos.push(video);
    }
  }
}
state.all_existing = state.items.length > 0 && state.pending.length === 0;
return state;
})()

(function () {
var state = JSON.parse(JSON.stringify(global.scan_state));
if (state.has_more) {
  if (typeof state.next_cursor !== 'string' || !state.next_cursor || state.visited_cursors.indexOf(state.next_cursor) >= 0) throw new Error('分页游标缺失或重复，停止以避免漏数据或无限循环');
  if (state.page >= global.max_pages) throw new Error('达到 max_pages 但仍有下一页，本次扫描未完成');
  state.cursor = state.next_cursor;
  state.visited_cursors.push(state.cursor);
}
return state;
})()

(function () {
var settings = output.configure_push.push_settings;
var creator = output.validate.creator;
var video = global.notification_state.pending[global.notification_state.index];
if (!video) throw new Error('待通知视频不存在');
var values = {username:creator.username,remark:creator.remark,title:video.title.slice(0, 1500),video_id:video.oid,published_at:String(video.published_at)};
var content = settings.message_template.replace(/\{([^{}]+)\}/g, function (_, name) {
  if (!Object.prototype.hasOwnProperty.call(values, name)) throw new Error('消息模板包含未知占位符：' + name);
  return String(values[name]);
});
var body = settings.method === 'wecom' ? {msgtype:'text',text:{content:content}} : {content:content,username:creator.username,remark:creator.remark,video_id:video.oid,title:video.title,published_at:video.published_at};
return {body:body};
})()

(function () {
var response = output.notify.webhook_response;
var status = output.notify.webhook_response_status;
if (!(status >= 200 && status < 300)) throw new Error('消息推送失败，本次运行停止，可下次重新检查');
if (output.configure_push.push_settings.method === 'wecom') {
  if (!response || Number(response.errcode) !== 0) throw new Error('企业微信通知失败，本次运行停止，可下次重新检查');
} else if (response && typeof response === 'object') {
  if (response.success === false || response.ok === false || (response.code !== undefined && Number(response.code) !== 0 && Number(response.code) !== 200) || (response.errcode !== undefined && Number(response.errcode) !== 0)) throw new Error('Webhook 返回推送失败，本次运行停止，可下次重新检查');
}
var state = JSON.parse(JSON.stringify(global.notification_state));
state.index += 1;
return state;
})()
